def __exit__(self, exc_type, exc_value, traceback):
    try:
        if self.stdin is not None and not self.stdin.closed:
            self.stdin.flush()
            self.stdin.close()

        if exc_type is not None or self._abort:
            for command in self.commands:
                command.wait()
                if command.stdout is not None:
                    command.stdout.close()

        else:
            for command in self.commands:
                command.finish()
    except Exception:
        if exc_type:
            # Re-raise inner exception rather than complaints during
            # pipeline shutdown.
            raise exc_type(exc_value).with_traceback(traceback)
        else:
            raise

def wait(self):
    while True:
        if self._process.poll() is not None:
            break
        else:
            sleep(0.1)

    return self._process.wait()

def finish(self):
    retcode = self.wait()

    if self.stdout is not None:
        self.stdout.close()

    if retcode != 0:
        raise UserCritical(
            msg='pipeline process did not exit gracefully',
            detail='"{0}" had terminated with the exit status {1}.'
            .format(" ".join(self._command), retcode))

