def running_size(self, segment):
    byts = 0
    try:
        sd = self.seg_dir(segment)
        for s in os.listdir(sd):
            byts += path.getsize(path.join(sd, s))

        return byts
    except EnvironmentError as e:
        if e.errno == errno.ENOENT:
            return byts

        raise

def clear_except(self, retained_segments):
    sn = set(s.name for s in retained_segments)

    try:
        for n in os.listdir(self.running):
            if n not in sn and re.match(storage.SEGMENT_REGEXP, n):
                try:
                    shutil.rmtree(path.join(self.running, n))
                except EnvironmentError as e:
                    if e.errno != errno.ENOENT:
                        raise
    except EnvironmentError as e:
        if e.errno != errno.ENOENT:
            raise

    try:
        for n in os.listdir(self.prefetched_dir):
            if n not in sn and re.match(storage.SEGMENT_REGEXP, n):
                try:
                    os.remove(path.join(self.prefetched_dir, n))
                except EnvironmentError as e:
                    if e.errno != errno.ENOENT:
                        raise
    except EnvironmentError as e:
        if e.errno != errno.ENOENT:
            raise

def promote(self, segment, destination):
    source = path.join(self.prefetched_dir, segment.name)
    os.rename(source, destination)

def _cut_batch(self):
    # Attempt to obtain as much work as possible, up to the
    # maximum able to be processed by S3 at one time,
    # PAGINATION_MAX.
    page = []

    try:
        for i in range(self.PAGINATION_MAX):
            page.append(self._q.get_nowait())
    except queue.Empty:
        pass
    except Exception:
        # In event everything goes sideways while dequeuing,
        # carefully un-lock the queue.
        for i in range(len(page)):
            self._q.task_done()
        raise

    return page

def _build_restore_paths(self, restore_spec):
    path_prefix = restore_spec['base_prefix']
    tblspc_prefix = os.path.join(path_prefix, 'pg_tblspc')

    if not os.path.isdir(path_prefix):
        os.mkdir(path_prefix, DEFAULT_DIR_MODE)

    if not os.path.isdir(tblspc_prefix):
        os.mkdir(tblspc_prefix, DEFAULT_DIR_MODE)

    for tblspc in restore_spec['tablespaces']:
        dest = os.path.join(path_prefix,
                            restore_spec[tblspc]['link'])
        source = restore_spec[tblspc]['loc']
        if not os.path.isdir(source):
            os.mkdir(source, DEFAULT_DIR_MODE)
        os.symlink(source, dest)

